  /**
   * Parses image response from OpenRouter API
   * OpenRouter returns images in an 'images' array within the assistant message
   *
   * @private
   */
  private parseImageResponse(data: any): { base64?: string; url?: string } {
    // OpenRouter returns images as base64 data URLs in the 'images' array
    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }

    try {
      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));

      if (data.choices && data.choices[0] && data.choices[0].message) {
        const message = data.choices[0].message;

        // Primary format: images array (OpenRouter standard)
        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
          const imageData = message.images[0];
          console.log('[ImageGen] Found image in images array, type:', typeof imageData);

          // Images are returned as data URLs (data:image/png;base64,...)
          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
            return { base64: imageData };
          }

          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
          if (typeof imageData === 'object') {
            // Check for image_url.url format (OpenRouter Gemini format)
            if (imageData.image_url?.url) {
              console.log('[ImageGen] Found image in image_url.url format');
              const url = imageData.image_url.url;
              if (url.startsWith('data:image')) {
                return { base64: url };
              }
              return { url };
            }
            // Check for b64_json format
            if (imageData.b64_json) {
              return { base64: `data:image/png;base64,${imageData.b64_json}` };
            }
            // Check for direct base64/url
            if (imageData.base64) {
              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
            }
            if (imageData.url) {
              return { url: imageData.url };
            }
          }
        }

        // Check content for embedded base64 or URLs
        const content = message.content;
        if (typeof content === 'string') {
          // Check if content contains base64 image data
          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
          if (base64Match) {
            console.log('[ImageGen] Found base64 image in content');
            return { base64: base64Match[0] };
          }

          // Check for URL in content
          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
          if (urlMatch) {
            console.log('[ImageGen] Found URL in content');
            return { url: urlMatch[0] };
          }
        }

        // Check for structured image data (fallback)
        if (message.image) {
          console.log('[ImageGen] Found image in message.image');
          return {
            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
            url: message.image.url,
          };
        }
      }

      // Fallback: return empty (will need to handle in caller)
      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
      if (data.choices?.[0]?.message) {
        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
      }
      return {};
    } catch (error) {
      console.error('[ImageGen] Error parsing image response:', error);
      return {};
    }
  }

  /**
   * Client-side rate limiting check
   * Limits to approximately 10 requests per minute
   *
   * @private
   */
  private checkRateLimit(): boolean {
    const now = Date.now();
    const minuteAgo = now - 60000;

    // Reset counter if a minute has passed
    if (this.lastRequestTime < minuteAgo) {
      this.requestCount = 0;
    }

    // Check if under limit
    if (this.requestCount >= 10) {
      return false;
    }

    // Update counters
    this.requestCount++;
    this.lastRequestTime = now;

    return true;
  }

  /**
   * Checks if error is non-retryable (auth, validation, etc.)
   *
   * @private
   */
  private isNonRetryableError(error: any): boolean {
    if (!error) return false;

    const errorMessage = error.message || error.toString();

    // Don't retry authentication errors
    if (errorMessage.includes('401') || errorMessage.includes('403')) {
      return true;
    }

    // Don't retry validation errors
    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
      return true;
    }

    // Don't retry rate limit errors (need to wait)
    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
      return true;
    }

    return false;
  }

  /**
   * Sleep utility for retry delays
   *
   * @private
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * Creates a new OpenRouter image client with API key from environment
 *
 * @returns OpenRouterImageClient instance or null if API key not available
 *
 * @example
 * const client = createImageClient();
 * if (client) {
 *   const response = await client.generateOutfitImage(description);
 * }
 */
export function createImageClient(): OpenRouterImageClient | null {
  const apiKey = process.env.OPENROUTER_API_KEY;

  if (!apiKey) {
    console.warn('[ImageGen] OPENROUTER_API_KEY not found in environment');
    return null;
  }

  try {
    return new OpenRouterImageClient(apiKey);
  } catch (error) {
    console.error('[ImageGen] Failed to create image client:', error);
    return null;
  }
}

'use client'

import type { Product } from '@/lib/types'

interface FlatLayCompositeProps {
  items: Product[]
}

interface CategorizedItems {
  mainItem: Product | null
  shoes: Product[]
  accessories: Product[]
}

/**
 * Categorizes outfit items into main garment, shoes, and accessories
 * Uses case-insensitive matching on category and subCategory fields
 */
function categorizeItems(items: Product[]): CategorizedItems {
  const mainCategories = ['dress', 'top', 'blouse', 'shirt', 'pants', 'skirt', 'jacket', 'blazer', 'coat', 'sweater', 'cardigan', 'jumpsuit', 'romper', 'suit', 'vest', 'tee', 't-shirt']
  const shoeCategories = ['shoes', 'shoe', 'footwear', 'heels', 'heel', 'sneakers', 'sneaker', 'sandals', 'sandal', 'boots', 'boot', 'loafers', 'loafer', 'flats', 'flat', 'pumps', 'pump', 'mules', 'mule', 'oxfords', 'oxford']

  let mainItem: Product | null = null
  const shoes: Product[] = []
  const accessories: Product[] = []

  for (const item of items) {
    const category = (item.category || '').toLowerCase()
    const subCategory = (item.subCategory || '').toLowerCase()
    const combined = `${category} ${subCategory}`

    const isShoe = shoeCategories.some(sc => combined.includes(sc))
    const isMain = mainCategories.some(mc => combined.includes(mc))

    if (isShoe) {
      shoes.push(item)
    } else if (isMain && !mainItem) {
      mainItem = item
    } else if (isMain) {
      // Additional main items become accessories
      accessories.push(item)
    } else {
      accessories.push(item)
    }
  }

  // If no main item found, use the first item with an image
  if (!mainItem && items.length > 0) {
    const itemWithImage = items.find(i => i.imageUrl)
    if (itemWithImage) {
      mainItem = itemWithImage
      // Remove from other arrays if it was placed there
      const shoeIdx = shoes.indexOf(itemWithImage)
      if (shoeIdx > -1) shoes.splice(shoeIdx, 1)
      const accIdx = accessories.indexOf(itemWithImage)
      if (accIdx > -1) accessories.splice(accIdx, 1)
    } else {
      mainItem = items[0]
    }
  }

  return { mainItem, shoes, accessories }
}

/**
 * FlatLayComposite - Creates a CSS-based flat-lay aesthetic composition of outfit items
 * Arranges items in an artistic flat-lay style using CSS transforms and absolute positioning
 */
export function FlatLayComposite({ items }: FlatLayCompositeProps) {
  if (!items || items.length === 0) {
    return (
      <div className="w-full h-full bg-white flex items-center justify-center">
        <span className="text-gray-400 text-xs">No items</span>
      </div>
    )
  }

  const { mainItem, shoes, accessories } = categorizeItems(items)

  // Single item - display centered
  if (items.length === 1 && mainItem) {
    return (
      <div className="w-full h-full bg-white relative overflow-hidden">
        <div className="absolute inset-0 flex items-center justify-center p-2">
          {mainItem.imageUrl ? (
            <img
              src={mainItem.imageUrl}
              alt={mainItem.name}
              className="max-w-full max-h-full object-contain drop-shadow-md"
            />
          ) : (
            <div className="w-full h-full bg-gray-100 flex items-center justify-center">
              <span className="text-gray-400 text-xs text-center px-2">{mainItem.name}</span>
            </div>
          )}
        </div>
      </div>
    )
  }

  // Get first shoe and first accessory for composition
  const shoe = shoes[0]
  const accessory = accessories[0]
  // Additional accessories for more complex compositions
  const secondAccessory = accessories[1]

  return (
    <div className="w-full h-full bg-white relative overflow-hidden">
      {/* Main item - large, center-left position */}
      {mainItem && mainItem.imageUrl && (
        <div
          className="absolute"
          style={{
            top: '8%',
            left: '15%',
            width: '70%',
            height: '75%',
            zIndex: 1,
            transform: 'rotate(-2deg)',
          }}
        >
          <img
            src={mainItem.imageUrl}
            alt={mainItem.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Shoes - positioned at bottom-left with rotation */}
      {shoe && shoe.imageUrl && (
        <div
          className="absolute"
          style={{
            bottom: '5%',
            left: '3%',
            width: '38%',
            height: '35%',
            zIndex: 3,
            transform: 'rotate(-12deg)',
          }}
        >
          <img
            src={shoe.imageUrl}
            alt={shoe.name}
            className="w-full h-full object-contain drop-shadow-lg"
          />
        </div>
      )}

      {/* Primary accessory - positioned at top-right or bottom-right with rotation */}
      {accessory && accessory.imageUrl && (
        <div
          className="absolute"
          style={{
            top: '5%',
            right: '3%',
            width: '32%',
            height: '30%',
            zIndex: 2,
            transform: 'rotate(10deg)',
          }}
        >
          <img
            src={accessory.imageUrl}
            alt={accessory.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Secondary accessory - positioned at bottom-right */}
      {secondAccessory && secondAccessory.imageUrl && (
        <div
          className="absolute"
          style={{
            bottom: '8%',
            right: '5%',
            width: '28%',
            height: '25%',
            zIndex: 4,
            transform: 'rotate(5deg)',
          }}
        >
          <img
            src={secondAccessory.imageUrl}
            alt={secondAccessory.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Fallback for main item without image */}
      {mainItem && !mainItem.imageUrl && (
        <div
          className="absolute bg-gray-100 flex items-center justify-center rounded"
          style={{
            top: '10%',
            left: '10%',
            width: '65%',
            height: '70%',
            zIndex: 1,
          }}
        >
          <span className="text-gray-400 text-xs text-center px-2">{mainItem.name}</span>
        </div>
      )}
    </div>
  )
}

